const sampleData = items[0].json;
const entityType = $node["Webhook Trigger"].json.body.entityType;

// Veri yapısını analiz et
function analyzeStructure(obj, path = '') {
  const fields = [];

  for (const [key, value] of Object.entries(obj)) {
    const fieldPath = path ? `${path}.${key}` : key;
    const fieldType = Array.isArray(value) ? 'array' : typeof value;

    fields.push({
      path: fieldPath,
      type: fieldType,
      sampleValue: fieldType === 'object' ? null : value
    });

    if (fieldType === 'object' && value !== null) {
      fields.push(...analyzeStructure(value, fieldPath));
    } else if (fieldType === 'array' && value.length > 0 && typeof value[0] === 'object') {
      fields.push(...analyzeStructure(value[0], `${fieldPath}[0]`));
    }
  }

  return fields;
}

const structure = analyzeStructure(sampleData);

// GrandNode field mapping önerileri
const mappingSuggestions = {
  product: {
    'name|title|productName': 'Name',
    'description|desc|fullDescription': 'FullDescription',
    'shortDescription|summary': 'ShortDescription',
    'price|cost|amount': 'Price',
    'sku|code|productCode': 'Sku',
    'stock|quantity|inventory': 'StockQuantity',
    'image|picture|photo': 'ProductPictures',
    'category|categoryId': 'ProductCategories',
    'active|enabled|published': 'Published',
    'weight': 'Weight',
    'width': 'Width',
    'height': 'Height',
    'length': 'Length'
  },
  category: {
    'name|title|categoryName': 'Name',
    'description|desc': 'Description',
    'parent|parentId|parentCategory': 'ParentCategoryId',
    'image|picture|icon': 'PictureId',
    'order|displayOrder|sortOrder': 'DisplayOrder',
    'active|enabled|published': 'Published',
    'showOnHomePage': 'ShowOnHomePage',
    'includeInMenu|showInMenu': 'IncludeInMenu'
  },
  order: {
    'orderNumber|orderId|id': 'OrderNumber',
    'customer|customerId': 'CustomerId',
    'email|customerEmail': 'BillingAddress.Email',
    'total|totalAmount|grandTotal': 'OrderTotal',
    'items|orderItems|products': 'OrderItems',
    'status|orderStatus': 'OrderStatusId',
    'paymentMethod|payment': 'PaymentMethodSystemName',
    'shippingMethod|shipping': 'ShippingMethod',
    'createdAt|orderDate|date': 'CreatedOnUtc'
  }
};

// Mapping önerilerini oluştur
const suggestions = mappingSuggestions[entityType] || {};
const mappings = [];

for (const field of structure) {
  let grandNodeField = null;

  // Field adına göre eşleştirme önerisi bul
  for (const [patterns, targetField] of Object.entries(suggestions)) {
    const fieldNameLower = field.path.toLowerCase();
    const patternList = patterns.split('|');

    if (patternList.some(pattern => fieldNameLower.includes(pattern))) {
      grandNodeField = targetField;
      break;
    }
  }

  mappings.push({
    sourcePath: field.path,
    sourceType: field.type,
    targetField: grandNodeField,
    transformFunction: null,
    required: false
  });
}

return [{
  json: {
    entityType,
    structure,
    mappings,
    sampleData
  }
}];

const mappingData = items[0].json;
const platformName = $node["Webhook Trigger"].json.body.platformName;

// Dönüşüm fonksiyonları oluştur
const transformFunctions = {
  'toBoolean': 'value => value === true || value === "true" || value === 1 || value === "1"',
  'toString': 'value => String(value || "")',
  'toNumber': 'value => Number(value) || 0',
  'toDecimal': 'value => parseFloat(value) || 0',
  'toDate': 'value => new Date(value).toISOString()',
  'toArray': 'value => Array.isArray(value) ? value : [value]',
  'toLowerCase': 'value => String(value).toLowerCase()',
  'toUpperCase': 'value => String(value).toUpperCase()'
};

// Mapping'lere dönüşüm fonksiyonları ekle
const enhancedMappings = mappingData.mappings.map(mapping => {
  let transform = null;

  // Tip uyumsuzluklarını tespit et ve dönüşüm öner
  if (mapping.targetField) {
    if (mapping.targetField.includes('Price') || mapping.targetField.includes('Cost')) {
      transform = 'toDecimal';
    } else if (mapping.targetField.includes('Published') || mapping.targetField.includes('Active')) {
      transform = 'toBoolean';
    } else if (mapping.targetField.includes('Date') || mapping.targetField.includes('CreatedOn')) {
      transform = 'toDate';
    } else if (mapping.targetField.includes('Quantity') || mapping.targetField.includes('Order')) {
      transform = 'toNumber';
    }
  }

  return {
    ...mapping,
    transformFunction: transform
  };
});

// Validasyon kuralları
const validationRules = {
  product: {
    'Name': { required: true, maxLength: 400 },
    'Sku': { required: true, maxLength: 400 },
    'Price': { required: true, min: 0 },
    'StockQuantity': { required: false, min: 0 }
  },
  category: {
    'Name': { required: true, maxLength: 400 },
    'DisplayOrder': { required: false, min: 0 }
  },
  order: {
    'CustomerId': { required: true },
    'OrderTotal': { required: true, min: 0 }
  }
};

const rules = validationRules[mappingData.entityType] || {};

// Required field'ları işaretle
const finalMappings = enhancedMappings.map(mapping => {
  if (mapping.targetField && rules[mapping.targetField]) {
    mapping.required = rules[mapping.targetField].required || false;
  }
  return mapping;
});

return [{
  json: {
    platformName,
    entityType: mappingData.entityType,
    mappings: finalMappings,
    transformFunctions,
    validationRules: rules
  }
}];
